// Session tokens bind a connection's clientId to a server-issued credential.
//
// Why this exists: clientId used to be whatever the client put in the URL. Since
// the owner and editor grants are keyed by clientId, anyone who saw a member's
// clientId in presence could reconnect with it and inherit that member's role.
// A session token is an HMAC over (room, clientId); the server only trusts a
// clientId that is either freshly generated by the server or carried by a valid
// token. Tokens are deliberately a different token type from readonly links so
// the two credentials can never be substituted for each other.
package auth

import (
	"crypto/subtle"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// ErrBadSession means the session token is malformed or its signature failed.
var ErrBadSession = errors.New("auth: bad session token")

// sessionHeader marks the token type. Keep it distinct from tokenHeader (CDRT):
// presenting a readonly token as a session (or vice versa) must fail even though
// both are signed with the same process secret.
var sessionHeader = base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"HS256","typ":"CDRS"}`))

// SessionClaims is the payload of a session token.
type SessionClaims struct {
	Room      string `json:"code"`
	ClientID  string `json:"cid"`
	IssuedAt  int64  `json:"iat"`
	ExpiresAt int64  `json:"exp"`
}

// IssueSession signs a session token for one room/clientId pair.
func (s *TokenSigner) IssueSession(room, cid string, ttl time.Duration, now time.Time) (string, SessionClaims, error) {
	if room == "" || cid == "" {
		return "", SessionClaims{}, errors.New("auth: session requires room and client id")
	}
	if ttl <= 0 {
		return "", SessionClaims{}, errors.New("auth: session ttl must be positive")
	}
	claims := SessionClaims{
		Room:      room,
		ClientID:  cid,
		IssuedAt:  now.UnixMilli(),
		ExpiresAt: now.Add(ttl).UnixMilli(),
	}
	payload, err := json.Marshal(claims)
	if err != nil {
		return "", SessionClaims{}, fmt.Errorf("auth: encode session claims: %w", err)
	}
	signingInput := sessionHeader + "." + base64.RawURLEncoding.EncodeToString(payload)
	return signingInput + "." + s.sign(signingInput), claims, nil
}

// VerifySession checks the signature, type, room binding and expiry.
//
// The room is part of the signed claims: a token minted for room A cannot be
// replayed against room B even if the attacker controls the query string.
func (s *TokenSigner) VerifySession(token, wantRoom string, now time.Time) (SessionClaims, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 || parts[0] != sessionHeader {
		return SessionClaims{}, ErrBadSession
	}
	signingInput := parts[0] + "." + parts[1]
	if subtle.ConstantTimeCompare([]byte(parts[2]), []byte(s.sign(signingInput))) != 1 {
		return SessionClaims{}, ErrBadSession
	}
	raw, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return SessionClaims{}, ErrBadSession
	}
	var claims SessionClaims
	if err := json.Unmarshal(raw, &claims); err != nil {
		return SessionClaims{}, ErrBadSession
	}
	if claims.Room == "" || claims.Room != wantRoom || claims.ClientID == "" {
		return SessionClaims{}, ErrBadSession
	}
	if claims.ExpiresAt <= 0 || now.UnixMilli() >= claims.ExpiresAt {
		return SessionClaims{}, ErrBadSession
	}
	return claims, nil
}
